import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Login from "./pages/Login";
import Details from "./pages/Details";
import PhotoResult from "./pages/PhotoResult";
import EmployeeList from "./components/EmployeeList"; // your employee table
import SalaryChart from "./pages/SalaryChart"; // chart page
import ProtectedRoute from "./components/ProtectedRoute"; // route protection

function App() {
  return (
    <Router>
      <Routes>
        {/* Public route */}
        <Route path="/" element={<Login />} />

        {/* Protected routes */}
        <Route
          path="/list"
          element={
            <ProtectedRoute>
              <EmployeeList />
            </ProtectedRoute>
          }
        />
        <Route
          path="/chart"
          element={
            <ProtectedRoute>
              <SalaryChart />
            </ProtectedRoute>
          }
        />

        {/* Other routes */}
        <Route path="/details" element={<Details />} />
        <Route path="/photo" element={<PhotoResult />} />
      </Routes>
    </Router>
  );
}

export default App;
